                elseif typeFunction(k) == "string" and k:match("^[%a_][%w_]*$") then
                    keyStr = k
                else
                    keyStr = "[" .. serializeValue(k, depth + 1, visited) .. "]"
                end
                local valStr = serializeValue(v, depth + 1, visited)
                if keyStr then
